SOURCE_CODE = 'import math, random, sys\nimport pygame\nfrom pygame.math import Vector2\n\npygame.init()\nW, H = 960, 680\nFPS = 60\n\nPALETTES = {\n    \'neon\': ((6,8,18),(40,255,190),(255,70,180)),\n    \'space\': ((3,4,16),(80,220,255),(255,90,70)),\n    \'lava\': ((15,5,8),(255,110,25),(255,220,80)),\n    \'ice\': ((6,18,32),(110,235,255),(220,255,255)),\n    \'storm\': ((8,10,24),(150,210,255),(255,255,255)),\n}\n\nclass Particles:\n    def __init__(self): self.items=[]\n    def burst(self,pos,color,n=30,speed=6):\n        for _ in range(n):\n            a=random.random()*math.tau\n            self.items.append([Vector2(pos),Vector2(math.cos(a),math.sin(a))*random.uniform(1,speed),random.randint(25,70),color,random.randint(2,5)])\n    def update(self):\n        for p in self.items[:]:\n            p[0]+=p[1]; p[1]*=.97; p[2]-=1\n            if p[2]<=0:self.items.remove(p)\n    def draw(self,surf):\n        g=pygame.Surface(surf.get_size(),pygame.SRCALPHA)\n        for p in self.items: pygame.draw.circle(g,(*p[3],min(255,p[2]*5)),p[0],p[4])\n        surf.blit(g,(0,0),special_flags=pygame.BLEND_ADD)\n\ndef starfield(screen,t,count=140):\n    random.seed(4)\n    for i in range(count):\n        x=(random.randrange(W)+int(t*(10+i%5)))%W\n        y=random.randrange(H)\n        r=1+i%3\n        c=100+i%150\n        pygame.draw.circle(screen,(c,c,min(255,c+25)),(x,y),r)\n    random.seed()\n\ndef glow_circle(screen,pos,color,r):\n    g=pygame.Surface((W,H),pygame.SRCALPHA)\n    for k,a in [(2.4,25),(1.8,45),(1.3,70)]: pygame.draw.circle(g,(*color,a),pos,int(r*k))\n    screen.blit(g,(0,0),special_flags=pygame.BLEND_ADD)\n\ndef text(screen,font,msg,pos,center=False,color=(255,255,255)):\n    img=font.render(msg,True,color)\n    screen.blit(img,img.get_rect(center=pos) if center else pos)\n\ndef run(mode):\n    fn=globals().get(\'game_\'+mode)\n    if not fn: raise ValueError(mode)\n    fn()\n\ndef game_neon_snake():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Neon Snake\')\n    clock=pygame.time.Clock();font=pygame.font.Font(None,42);CELL=25;cols=W//CELL;rows=H//CELL\n    snake=[(18,13),(17,13),(16,13)];d=(1,0);nd=d;food=(27,13);p=Particles();score=0;over=False\n    ev=pygame.USEREVENT+1;pygame.time.set_timer(ev,95)\n    while True:\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN:\n                m={pygame.K_UP:(0,-1),pygame.K_DOWN:(0,1),pygame.K_LEFT:(-1,0),pygame.K_RIGHT:(1,0)}\n                if e.key in m and m[e.key]!=(-d[0],-d[1]):nd=m[e.key]\n                if e.key==pygame.K_r:snake[:]=[(18,13),(17,13),(16,13)];d=nd=(1,0);food=(27,13);score=0;over=False;p.items.clear()\n            if e.type==ev and not over:\n                d=nd;h=(snake[0][0]+d[0],snake[0][1]+d[1]);body=snake if h==food else snake[:-1]\n                if not(0<=h[0]<cols and 0<=h[1]<rows) or h in body:over=True;p.burst((snake[0][0]*CELL+12,snake[0][1]*CELL+12),(40,255,190),90)\n                else:\n                    snake.insert(0,h)\n                    if h==food:\n                        score+=1;p.burst((food[0]*CELL+12,food[1]*CELL+12),(255,70,180),45)\n                        spaces=[(x,y) for y in range(rows) for x in range(cols) if (x,y) not in snake];food=random.choice(spaces)\n                    else:snake.pop()\n        t=pygame.time.get_ticks()/1000;screen.fill((5,8,18))\n        for x in range(0,W,CELL):pygame.draw.line(screen,(8,18+int(8*math.sin(t+x*.03)),32),(x,0),(x,H))\n        for y in range(0,H,CELL):pygame.draw.line(screen,(8,18+int(8*math.sin(t+y*.03)),32),(0,y),(W,y))\n        fx,fy=food;glow_circle(screen,(fx*CELL+12,fy*CELL+12),(255,70,180),16);pygame.draw.circle(screen,(255,110,200),(fx*CELL+12,fy*CELL+12),8)\n        for i,(x,y) in enumerate(snake):\n            pos=(x*CELL+12,y*CELL+12);glow_circle(screen,pos,(40,255,190),14);pygame.draw.circle(screen,(90,255,220) if i==0 else (20,160,130),pos,10 if i==0 else 8)\n        p.update();p.draw(screen);text(screen,font,f\'Score {score}\',(20,18))\n        if over:text(screen,font,\'GAME OVER — Press R\',(W//2,H//2),True)\n        pygame.display.flip();clock.tick(FPS)\n\ndef game_galaxy_defender():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Galaxy Defender\');clock=pygame.time.Clock();font=pygame.font.Font(None,40)\n    ship=Vector2(W/2,H-80);shots=[];en=[];p=Particles();score=0;spawn=0;alive=True\n    while True:\n        dt=clock.tick(FPS)/1000\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN and e.key==pygame.K_r:ship.update(W/2,H-80);shots.clear();en.clear();p.items.clear();score=0;alive=True\n        keys=pygame.key.get_pressed()\n        if alive:\n            mv=Vector2(keys[pygame.K_RIGHT]-keys[pygame.K_LEFT],keys[pygame.K_DOWN]-keys[pygame.K_UP]);mv=mv.normalize() if mv.length_squared() else mv;ship+=mv*420*dt;ship.x=max(30,min(W-30,ship.x));ship.y=max(30,min(H-30,ship.y))\n            if keys[pygame.K_SPACE] and (not shots or shots[-1][0].distance_to(ship)>50):shots.append([Vector2(ship),Vector2(0,-720)])\n        spawn+=dt\n        if alive and spawn>max(.22,.8-score*.001):spawn=0;en.append([Vector2(random.randint(30,W-30),-30),random.uniform(100,230),random.randint(16,30)])\n        for s in shots[:]:s[0]+=s[1]*dt;shots.remove(s) if s[0].y<-30 else None\n        for e in en[:]:\n            e[0].y+=e[1]*dt;e[0].x+=math.sin(pygame.time.get_ticks()*.004+e[0].y*.02)*80*dt\n            if e[0].y>H+40:en.remove(e)\n            elif alive and e[0].distance_to(ship)<e[2]+22:alive=False;p.burst(ship,(80,220,255),120,8)\n            else:\n                for s in shots[:]:\n                    if s[0].distance_to(e[0])<e[2]+5:\n                        if s in shots:shots.remove(s)\n                        if e in en:en.remove(e)\n                        score+=10;p.burst(e[0],(255,90,70),45);break\n        screen.fill((3,4,16));starfield(screen,pygame.time.get_ticks()/1000)\n        for s in shots:glow_circle(screen,s[0],(80,220,255),8);pygame.draw.circle(screen,(230,255,255),s[0],4)\n        for e in en:glow_circle(screen,e[0],(255,70,90),e[2]);pygame.draw.polygon(screen,(225,70,95),[(e[0].x,e[0].y-e[2]),(e[0].x-e[2],e[0].y+e[2]),(e[0].x+e[2],e[0].y+e[2])])\n        if alive:\n            glow_circle(screen,ship,(60,210,255),24);pygame.draw.polygon(screen,(90,220,255),[(ship.x,ship.y-28),(ship.x-22,ship.y+22),(ship.x,ship.y+12),(ship.x+22,ship.y+22)])\n            pygame.draw.polygon(screen,(255,180,60),[(ship.x-7,ship.y+20),(ship.x,ship.y+40+random.randint(0,10)),(ship.x+7,ship.y+20)])\n        p.update();p.draw(screen);text(screen,font,f\'Score {score}\',(20,20))\n        if not alive:text(screen,font,\'DESTROYED — Press R\',(W//2,H//2),True)\n        pygame.display.flip()\n\ndef game_crystal_breaker():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Crystal Breaker\');clock=pygame.time.Clock();font=pygame.font.Font(None,42)\n    paddle=pygame.Rect(W//2-85,H-50,170,18);ball=Vector2(W/2,H-90);v=Vector2(5,-6);pal=[(80,220,255),(150,90,255),(255,80,180),(70,255,160)];p=Particles();score=0;over=False\n    crystals=[[pygame.Rect(45+c*87,60+r*45,68,30),random.randrange(4),2] for r in range(6) for c in range(10)]\n    while True:\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN and e.key==pygame.K_r:paddle.centerx=W//2;ball.update(W//2,H-90);v.update(5,-6);crystals[:]=[[pygame.Rect(45+c*87,60+r*45,68,30),random.randrange(4),2] for r in range(6) for c in range(10)];score=0;over=False;p.items.clear()\n        k=pygame.key.get_pressed();paddle.x+=(k[pygame.K_RIGHT]-k[pygame.K_LEFT])*9;paddle.clamp_ip(screen.get_rect())\n        if not over:\n            ball+=v\n            if ball.x<10 or ball.x>W-10:v.x*=-1\n            if ball.y<10:v.y*=-1\n            if pygame.Rect(ball.x-9,ball.y-9,18,18).colliderect(paddle) and v.y>0:v.y=-abs(v.y);v.x+=(ball.x-paddle.centerx)*.02\n            for c in crystals[:]:\n                if pygame.Rect(ball.x-9,ball.y-9,18,18).colliderect(c[0]):v.y*=-1;c[2]-=1;p.burst(c[0].center,pal[c[1]],20);crystals.remove(c) if c[2]<=0 else None;score+=10 if c[2]<=0 else 0;break\n            if ball.y>H+20:over=True\n        screen.fill((8,7,20));t=pygame.time.get_ticks()/1000\n        for y in range(0,H,45):pygame.draw.line(screen,(20,18+int(8*math.sin(t+y)),50),(0,y),(W,y))\n        for r,ci,hp in crystals:\n            pts=[(r.centerx,r.top),(r.right,r.centery),(r.centerx,r.bottom),(r.left,r.centery)];pygame.draw.polygon(screen,pal[ci],pts);pygame.draw.polygon(screen,(255,255,255),pts,2)\n        pygame.draw.rect(screen,(220,240,255),paddle,border_radius=9);glow_circle(screen,ball,(100,220,255),20);pygame.draw.circle(screen,(255,255,255),ball,9)\n        p.update();p.draw(screen);text(screen,font,f\'Score {score}\',(20,16))\n        if over:text(screen,font,\'GAME OVER — Press R\',(W//2,H//2),True)\n        elif not crystals:text(screen,font,\'CRYSTALS CLEARED!\',(W//2,H//2),True)\n        pygame.display.flip();clock.tick(FPS)\n\ndef runner_theme(name,bg,accent):\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(name);clock=pygame.time.Clock();font=pygame.font.Font(None,42)\n    player=pygame.Rect(140,440,46,66);vy=0;ground=520;obs=[];p=Particles();score=0;speed=7;spawn=0;alive=True\n    while True:\n        dt=clock.tick(FPS)/1000\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN:\n                if e.key==pygame.K_SPACE and player.bottom>=ground:vy=-16\n                if e.key==pygame.K_r:player.topleft=(140,440);vy=0;obs.clear();p.items.clear();score=0;speed=7;spawn=0;alive=True\n        if alive:\n            vy+=38*dt;player.y+=int(vy)\n            if player.bottom>ground:player.bottom=ground;vy=0\n            spawn+=dt\n            if spawn>random.uniform(.8,1.35):spawn=0;h=random.choice([45,65,85]);obs.append(pygame.Rect(W+20,ground-h,random.choice([35,50]),h))\n            for o in obs[:]:\n                o.x-=int(speed)\n                if o.right<0:obs.remove(o);score+=1;speed=min(15,speed+.15)\n                elif o.colliderect(player):alive=False;p.burst(player.center,accent,80)\n        screen.fill(bg);t=pygame.time.get_ticks()/1000\n        for layer,(col,amp,base,sp) in enumerate([((30,20,40),80,390,.15),((55,28,45),60,445,.3),((85,35,40),35,490,.5)]):\n            pts=[(0,H)]+[(x,base-math.sin(x*.012+t*sp+layer)*amp) for x in range(0,W+40,40)]+[(W,H)];pygame.draw.polygon(screen,col,pts)\n        pygame.draw.rect(screen,(45,28,24),(0,ground,W,H-ground))\n        for x in range(0,W,40):pygame.draw.circle(screen,accent,(x,int(ground+24+math.sin(t*4+x*.03)*10)),7)\n        for o in obs:pygame.draw.rect(screen,(70,30,25),o,border_radius=8);pygame.draw.rect(screen,accent,o,3,border_radius=8)\n        pygame.draw.rect(screen,(90,220,255),player,border_radius=10);pygame.draw.circle(screen,(255,255,255),(player.centerx+10,player.y+18),5)\n        p.update();p.draw(screen);text(screen,font,f\'Distance {score}\',(20,20))\n        if not alive:text(screen,font,\'FALLEN — Press R\',(W//2,H//2),True)\n        pygame.display.flip()\n\ndef game_lava_runner(): runner_theme(\'Lava Runner\',(12,5,8),(255,95,25))\n\ndef game_orbit_duel():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Orbit Duel\');clock=pygame.time.Clock();font=pygame.font.Font(None,38);center=Vector2(W/2,H/2)\n    a=0;r=190;shots=[];en=[];p=Particles();score=0;hp=5;spawn=0\n    while True:\n        dt=clock.tick(FPS)/1000\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN and e.key==pygame.K_r:a=0;shots.clear();en.clear();p.items.clear();score=0;hp=5\n        k=pygame.key.get_pressed();a+=(k[pygame.K_RIGHT]-k[pygame.K_LEFT])*2.5*dt;r=max(90,min(280,r+(k[pygame.K_DOWN]-k[pygame.K_UP])*180*dt));ship=center+Vector2(math.cos(a),math.sin(a))*r\n        if k[pygame.K_SPACE] and (not shots or shots[-1][2]>.16):shots.append([Vector2(ship),(ship-center).normalize()*520,0])\n        for s in shots[:]:s[0]+=s[1]*dt;s[2]+=dt;shots.remove(s) if s[2]>2 else None\n        spawn+=dt\n        if spawn>.75 and hp>0:spawn=0;q=random.random()*math.tau;pos=center+Vector2(math.cos(q),math.sin(q))*500;en.append([pos,(center-pos).normalize()*random.uniform(50,100),random.randint(16,28)])\n        for e in en[:]:\n            e[0]+=e[1]*dt\n            if e[0].distance_to(center)<35:en.remove(e);hp-=1\n            else:\n                for s in shots[:]:\n                    if s[0].distance_to(e[0])<e[2]+6:\n                        if s in shots:shots.remove(s)\n                        if e in en:en.remove(e)\n                        score+=10;p.burst(e[0],(255,90,80),25);break\n        screen.fill((4,6,18));t=pygame.time.get_ticks()/1000\n        for rr in range(90,330,45):pygame.draw.circle(screen,(20,40+int(15*math.sin(t+rr)),70),center,rr,1)\n        glow_circle(screen,center,(70,120,255),50);pygame.draw.circle(screen,(90,140,255),center,28);pygame.draw.circle(screen,(220,240,255),center,10);pygame.draw.circle(screen,(80,160,255),center,int(r),1)\n        for s in shots:glow_circle(screen,s[0],(80,230,255),9);pygame.draw.circle(screen,(230,255,255),s[0],4)\n        for e in en:glow_circle(screen,e[0],(255,70,90),e[2]);pygame.draw.circle(screen,(220,70,90),e[0],e[2])\n        glow_circle(screen,ship,(100,255,210),22);pygame.draw.polygon(screen,(90,255,210),[(ship.x,ship.y-16),(ship.x-12,ship.y+12),(ship.x+12,ship.y+12)])\n        p.update();p.draw(screen);text(screen,font,f\'Score {score}   Core {hp}\',(20,20))\n        if hp<=0:text(screen,font,\'CORE LOST — Press R\',(W//2,H//2),True)\n        pygame.display.flip()\n\ndef collect_theme(name,bg,accent):\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(name);clock=pygame.time.Clock();font=pygame.font.Font(None,40);player=pygame.Rect(90,300,42,42);v=Vector2();p=Particles();score=0\n    walls=[pygame.Rect(0,0,W,25),pygame.Rect(0,H-25,W,25),pygame.Rect(0,0,25,H),pygame.Rect(W-25,0,25,H)]+[pygame.Rect(random.randint(90,W-170),random.randint(70,H-130),random.randint(60,150),random.randint(20,55)) for _ in range(18)]\n    gems=[Vector2(random.randint(50,W-50),random.randint(50,H-50)) for _ in range(14)]\n    while True:\n        dt=clock.tick(FPS)/1000\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN and e.key==pygame.K_r:player.topleft=(90,300);v.update();score=0\n        k=pygame.key.get_pressed();acc=Vector2(k[pygame.K_RIGHT]-k[pygame.K_LEFT],k[pygame.K_DOWN]-k[pygame.K_UP]);acc=acc.normalize()*650 if acc.length_squared() else acc;v+=acc*dt;v*=.985\n        if v.length()>420:v.scale_to_length(420)\n        old=player.copy();player.x+=int(v.x*dt)\n        if any(player.colliderect(w) for w in walls):player.x=old.x;v.x*=-.45\n        old=player.copy();player.y+=int(v.y*dt)\n        if any(player.colliderect(w) for w in walls):player.y=old.y;v.y*=-.45\n        for g in gems[:]:\n            if Vector2(player.center).distance_to(g)<30:gems.remove(g);score+=1;p.burst(g,accent,25)\n        screen.fill(bg)\n        for y in range(0,H,25):pygame.draw.line(screen,(10,30,50),(0,y),(W,y))\n        for w in walls:pygame.draw.rect(screen,(45,85,110),w,border_radius=8);pygame.draw.rect(screen,accent,w,2,border_radius=8)\n        t=pygame.time.get_ticks()/1000\n        for g in gems:\n            q=8+int(3*math.sin(t*5+g.x*.02));glow_circle(screen,g,accent,18);pygame.draw.polygon(screen,accent,[(g.x,g.y-q),(g.x+q*.7,g.y),(g.x,g.y+q),(g.x-q*.7,g.y)])\n        glow_circle(screen,player.center,accent,25);pygame.draw.rect(screen,(220,250,255),player,border_radius=10)\n        p.update();p.draw(screen);text(screen,font,f\'Crystals {score}\',(20,20))\n        if not gems:text(screen,font,\'CAVERN CLEARED!\',(W//2,H//2),True)\n        pygame.display.flip()\n\ndef game_ice_cavern(): collect_theme(\'Ice Cavern\',(7,18,34),(120,235,255))\n\ndef game_storm_dodger():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Storm Dodger\');clock=pygame.time.Clock();font=pygame.font.Font(None,40);player=pygame.Rect(W//2-25,H-90,50,50);bolts=[];rain=[[random.randrange(W),random.randrange(H),random.randint(12,28)] for _ in range(180)];score=0;spawn=0;alive=True;flash=0\n    while True:\n        dt=clock.tick(FPS)/1000\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN and e.key==pygame.K_r:player.center=(W//2,H-70);bolts.clear();score=0;spawn=0;alive=True;flash=0\n        k=pygame.key.get_pressed()\n        if alive:\n            player.x+=(k[pygame.K_RIGHT]-k[pygame.K_LEFT])*9;player.clamp_ip(screen.get_rect());spawn+=dt\n            if spawn>max(.35,1-score*.015):spawn=0;bolts.append([random.randint(40,W-40),0,random.randint(4,8),random.randint(14,24)])\n        for r in rain:r[1]+=r[2];(r.__setitem__(0,random.randrange(W)),r.__setitem__(1,-20)) if r[1]>H else None\n        for b in bolts[:]:\n            b[1]+=b[3]\n            if b[1]>H:bolts.remove(b);score+=1\n            elif alive and pygame.Rect(b[0]-b[2],b[1],b[2]*2,80).colliderect(player):alive=False;flash=255\n        flash=max(0,flash-12);screen.fill((8,10,24));t=pygame.time.get_ticks()/1000\n        for i in range(16):pygame.draw.circle(screen,(25,28,48),((i*80+int(t*12))%(W+160)-80,int(70+math.sin(i+t*.3)*25)),70)\n        for x,y,s in rain:pygame.draw.line(screen,(90,140,200),(x,y),(x-5,y+18),2)\n        g=pygame.Surface((W,H),pygame.SRCALPHA)\n        for x,y,wid,spd in bolts:\n            pts=[(x,y)];cx=x;cy=y\n            for _ in range(5):cx+=random.randint(-12,12);cy+=16;pts.append((cx,cy))\n            pygame.draw.lines(g,(180,220,255,180),False,pts,wid+4);pygame.draw.lines(screen,(240,250,255),False,pts,max(2,wid//2))\n        glow_circle(screen,player.center,(80,180,255),24);pygame.draw.rect(screen,(100,210,255),player,border_radius=12);screen.blit(g,(0,0),special_flags=pygame.BLEND_ADD)\n        if flash:ov=pygame.Surface((W,H),pygame.SRCALPHA);ov.fill((255,255,255,flash//3));screen.blit(ov,(0,0))\n        text(screen,font,f\'Survival {score}\',(20,20))\n        if not alive:text(screen,font,\'STRUCK — Press R\',(W//2,H//2),True)\n        pygame.display.flip()\n\ndef game_shadow_maze():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Shadow Maze\');clock=pygame.time.Clock();font=pygame.font.Font(None,38);player=Vector2(70,70)\n    walls=[pygame.Rect(0,0,W,25),pygame.Rect(0,H-25,W,25),pygame.Rect(0,0,25,H),pygame.Rect(W-25,0,25,H)]+[pygame.Rect(x,25 if i%2==0 else 190,25,430) for i,x in enumerate(range(120,860,100))]\n    goal=pygame.Rect(850,580,70,45);orbs=[Vector2(180,100),Vector2(380,560),Vector2(580,100),Vector2(780,520)];got=set()\n    while True:\n        dt=clock.tick(FPS)/1000\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.KEYDOWN and e.key==pygame.K_r:player.update(70,70);got.clear()\n        k=pygame.key.get_pressed();mv=Vector2(k[pygame.K_RIGHT]-k[pygame.K_LEFT],k[pygame.K_DOWN]-k[pygame.K_UP]);mv=mv.normalize()*230*dt if mv.length_squared() else mv\n        for ax in (0,1):\n            q=Vector2(player);q[ax]+=mv[ax]\n            if not any(pygame.Rect(q.x-12,q.y-12,24,24).colliderect(w) for w in walls):player=q\n        for i,o in enumerate(orbs):\n            if i not in got and player.distance_to(o)<24:got.add(i)\n        screen.fill((3,3,8));[pygame.draw.rect(screen,(35,35,50),w) for w in walls];pygame.draw.rect(screen,(80,220,140),goal,border_radius=8)\n        for i,o in enumerate(orbs):\n            if i not in got:pygame.draw.circle(screen,(255,220,80),o,8)\n        dark=pygame.Surface((W,H),pygame.SRCALPHA);dark.fill((0,0,0,235))\n        for rr,a in [(180,0),(145,35),(110,70),(80,110),(50,150)]:pygame.draw.circle(dark,(0,0,0,a),player,rr)\n        screen.blit(dark,(0,0));glow_circle(screen,player,(120,220,255),20);pygame.draw.circle(screen,(200,250,255),player,10);text(screen,font,f\'Orbs {len(got)}/4\',(20,20))\n        if len(got)==4 and goal.collidepoint(player):text(screen,font,\'ESCAPED THE MAZE!\',(W//2,H//2),True)\n        pygame.display.flip()\n\ndef game_plasma_pong():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Plasma Pong\');clock=pygame.time.Clock();font=pygame.font.Font(None,48);left=pygame.Rect(35,240,20,140);right=pygame.Rect(W-55,240,20,140);ball=Vector2(W/2,H/2);v=Vector2(7,5);trail=[];ls=rs=0\n    while True:\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n        k=pygame.key.get_pressed();left.y+=(k[pygame.K_s]-k[pygame.K_w])*9;right.y+=(k[pygame.K_DOWN]-k[pygame.K_UP])*9;left.clamp_ip(screen.get_rect());right.clamp_ip(screen.get_rect());ball+=v;trail.append([Vector2(ball),180])\n        if ball.y<12 or ball.y>H-12:v.y*=-1\n        br=pygame.Rect(ball.x-10,ball.y-10,20,20)\n        if br.colliderect(left) and v.x<0:v.x=abs(v.x)*1.03\n        if br.colliderect(right) and v.x>0:v.x=-abs(v.x)*1.03\n        if ball.x<-20:rs+=1;ball.update(W/2,H/2);v.update(7,random.choice([-5,5]))\n        if ball.x>W+20:ls+=1;ball.update(W/2,H/2);v.update(-7,random.choice([-5,5]))\n        for tr in trail[:]:tr[1]-=6;trail.remove(tr) if tr[1]<=0 else None\n        screen.fill((4,5,18));t=pygame.time.get_ticks()/1000\n        for y in range(0,H,35):pygame.draw.line(screen,(10,20+int(10*math.sin(t+y*.02)),45),(0,y),(W,y))\n        g=pygame.Surface((W,H),pygame.SRCALPHA)\n        for pos,a in trail:pygame.draw.circle(g,(100,80,255,a),pos,12)\n        for pad,col in [(left,(80,220,255)),(right,(255,80,190))]:pygame.draw.rect(g,(*col,100),pad.inflate(30,30),border_radius=18);pygame.draw.rect(screen,col,pad,border_radius=10)\n        pygame.draw.circle(g,(220,120,255,150),ball,35);pygame.draw.circle(screen,(255,255,255),ball,10);screen.blit(g,(0,0),special_flags=pygame.BLEND_ADD);text(screen,font,f\'{ls}      {rs}\',(W//2,50),True);pygame.display.flip();clock.tick(FPS)\n\ndef game_particle_arena():\n    screen=pygame.display.set_mode((W,H));pygame.display.set_caption(\'Particle Arena\');clock=pygame.time.Clock();font=pygame.font.Font(None,40);player=Vector2(W/2,H/2);shots=[];en=[];p=Particles();score=0;hp=100;spawn=0\n    while True:\n        dt=clock.tick(FPS)/1000\n        for e in pygame.event.get():\n            if e.type==pygame.QUIT:pygame.quit();sys.exit()\n            if e.type==pygame.MOUSEBUTTONDOWN and e.button==1 and hp>0:\n                d=Vector2(e.pos)-player\n                if d.length_squared():shots.append([Vector2(player),d.normalize()*720])\n            if e.type==pygame.KEYDOWN and e.key==pygame.K_r:player.update(W/2,H/2);shots.clear();en.clear();p.items.clear();score=0;hp=100\n        k=pygame.key.get_pressed();mv=Vector2(k[pygame.K_d]-k[pygame.K_a],k[pygame.K_s]-k[pygame.K_w]);mv=mv.normalize()*300*dt if mv.length_squared() else mv;player+=mv;player.x=max(20,min(W-20,player.x));player.y=max(20,min(H-20,player.y));spawn+=dt\n        if spawn>max(.18,.65-score*.0015) and hp>0:\n            spawn=0;side=random.randrange(4);pos=[Vector2(random.randrange(W),-20),Vector2(W+20,random.randrange(H)),Vector2(random.randrange(W),H+20),Vector2(-20,random.randrange(H))][side];en.append([pos,random.uniform(70,145),random.randint(13,28)])\n        for s in shots[:]:s[0]+=s[1]*dt;shots.remove(s) if not screen.get_rect().inflate(100,100).collidepoint(s[0]) else None\n        for e in en[:]:\n            d=player-e[0];e[0]+=d.normalize()*e[1]*dt if d.length_squared() else Vector2()\n            if e[0].distance_to(player)<e[2]+16:en.remove(e);hp-=12;p.burst(player,(255,80,80),40)\n            else:\n                for s in shots[:]:\n                    if s[0].distance_to(e[0])<e[2]+5:\n                        if s in shots:shots.remove(s)\n                        if e in en:en.remove(e)\n                        score+=10;p.burst(e[0],(255,100,180),35);break\n        screen.fill((7,7,14));starfield(screen,pygame.time.get_ticks()/1000,70)\n        for s in shots:glow_circle(screen,s[0],(100,220,255),9);pygame.draw.circle(screen,(220,255,255),s[0],4)\n        t=pygame.time.get_ticks()/1000\n        for e in en:\n            glow_circle(screen,e[0],(255,60,130),e[2]);pts=[]\n            for i in range(8):a=i*math.tau/8+t;rr=e[2]*(1 if i%2==0 else .55);pts.append(e[0]+Vector2(math.cos(a),math.sin(a))*rr)\n            pygame.draw.polygon(screen,(220,60,130),pts)\n        glow_circle(screen,player,(80,220,255),24);pygame.draw.circle(screen,(120,240,255),player,16);p.update();p.draw(screen);text(screen,font,f\'Score {score}   HP {max(0,hp)}\',(20,20))\n        if hp<=0:text(screen,font,\'ARENA LOST — Press R\',(W//2,H//2),True)\n        pygame.display.flip()\n\nif __name__ == "__main__":\n    run("plasma_pong")\n'
DEFAULT_OUTPUT = "09_plasma_pong.py"


def write_game(output_path: Path) -> None:
    output_path.write_text(SOURCE_CODE, encoding="utf-8")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate the standalone game source file."
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=Path.cwd() / DEFAULT_OUTPUT,
        help="Path where the game file should be written. Defaults to the current working directory.",
    )
    args = parser.parse_args()

    output_path = args.output.resolve()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    write_game(output_path)
    print(f"Created {output_path} from 09_plasma_pong.py.")


if __name__ == "__main__":
    main()
